-- Seed curated proof/case-study cards as published proof_card CMS entries.
-- Mirrors the evidence-classified static fallback and generated proof snapshot.
-- Signed publication scope is recorded offline; raw source documents stay outside
-- the proof-card payload. sort_order preserves the curated DOM order; image
-- dimensions reserve layout space. Idempotent. Apply via service-role connection.

on conflict (type, slug, locale) do update
  set title = excluded.title, status = excluded.status, payload = excluded.payload,
      seo = excluded.seo, published_at = coalesce(public.content_entries.published_at, now()), updated_at = now();

update public.content_entries set published_at = coalesce(published_at, now())
  where type = 'proof_card' and status = 'published';
